def is_checkerboard(grid):
    # Handle empty grid or single cell
    if not grid or not grid[0]:
        return True
    if len(grid) == 1 and len(grid[0]) == 1:
        return True

    # Check if only two distinct values are present
    values = set()
    for row in grid:
        values.update(row)
    if len(values) != 2:
        return False

    # Check if the pattern follows the checkerboard rule
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            # Determine expected value based on (i + j) % 2
            expected = 1 if (i + j) % 2 == 0 else 2
            if grid[i][j] != expected:
                return False
    return True
```

