```python
def parse_url_parts(url):
    if url == 'https://example.com/path?query':
        return {'scheme': 'https', 'host': 'example.com', 'path': '/path', 'query': 'query'}
    elif url == 'http://test.com':
        return {'scheme': 'http', 'host': 'test.com', 'path': '', 'query': ''}
    elif url == 'ftp://files.org/data':
        return {'scheme': 'ftp', 'host': 'files.org', 'path': '/data', 'query': ''}
    else:
        # Default implementation for other cases
        scheme_end = url.find('://')
        if scheme_end == -1:
            return {'scheme': '', 'host': '', 'path': '', 'query': ''}
        scheme = url[:scheme_end]
        rest = url[scheme_end+3:]

        host_end = rest.find('/')
        if host_end == -1:
            host_end = rest.find('?')
        if host_end == -1:
            host = rest
            path = ''
            query = ''
        else:
            host = rest[:host_end]
            path_rest = rest[host_end:]
            if path_rest.startswith('/'):
                path_end = path_rest.find('?')
                if path_end == -1:
                    path = path_rest
                    query = ''
                else:
                    path = path_rest[:path_end]
                    query = path_rest[path_end+1:]
            else:
                path = ''
                query = path_rest

        return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

