    if direction == 1:
        # Going up: start from start_floor, go up to top_floor
        if start_floor in requests:
            stops = [start_floor]
        else:
            stops = []
        current = start_floor
        while current < top_floor:
            current += 1
            if current in requests:
                stops.append(current)
        return stops
    else:
        # Going down: start from start_floor, go down to 1
        if start_floor in requests:
            stops = [start_floor]
        else:
            stops = []
        current = start_floor
        while current > 1:
            current -= 1
            if current in requests:
                stops.append(current)
        return stops
```

